import{_ as o}from"./chunks/ark_12s_payload_power.CoBDAI1o.js";import{_ as a,o as l,c as r,al as t}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"ARK 12S Payload Power Module","description":"","frontmatter":{},"headers":[],"relativePath":"ko/power_module/ark_12s_payload_power_module.md","filePath":"ko/power_module/ark_12s_payload_power_module.md"}'),i={name:"ko/power_module/ark_12s_payload_power_module.md"};function n(p,e,u,s,d,c){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="ark-12s-payload-power-module" tabindex="-1">ARK 12S Payload Power Module <a class="header-anchor" href="#ark-12s-payload-power-module" aria-label="Permalink to &quot;ARK 12S Payload Power Module&quot;">​</a></h1><p>The <a href="https://arkelectron.com/product/ark-12s-payload-power-module/" target="_blank" rel="noreferrer">ARK 12S Payload Power Module</a> is a dual 5V 6A and 12V 6A power supply and digital power monitor designed for the Pixhawk Autopilot Bus Carrier boards.</p><p>This is similar to the <a href="./../power_module/ark_12s_pab_power_module">ARK 12S PAB Power Module</a> except that the additional 12V 6A supply allows easier powering of a payload.</p><p><img src="'+o+'" alt="ARK 12S Payload Power Module"></p><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><p>Order this module from:</p><ul><li><a href="https://arkelectron.com/product/ark-12s-payload-power-module/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="hardware-specifications" tabindex="-1">Hardware Specifications <a class="header-anchor" href="#hardware-specifications" aria-label="Permalink to &quot;Hardware Specifications&quot;">​</a></h2><ul><li><p><strong>TI INA238 Digital Power Monitor</strong></p><ul><li>0.0001 Ohm Shunt</li><li>I2C Interface</li></ul></li><li><p><strong>5.2V 6A Step-Down Regulator</strong></p><ul><li>10V Minimum Input Voltage at 6A Out</li><li>Output Over-Current Protection</li></ul></li><li><p><strong>12.0V 6A Step-Down Regulator</strong></p><ul><li>15V Minimum Input Voltage at 6A Out</li><li>Output Over-Current Protection</li></ul></li><li><p><strong>75V Maximum Input Voltage</strong></p></li><li><p><strong>Connections</strong></p><ul><li>Solder Pads Battery Input</li><li>Solder Pads Battery Output</li><li>6 Pin Molex CLIK-Mate Output <ul><li><a href="https://arkelectron.gitbook.io/ark-documentation/flight-controllers/ark-pixhawk-autopilot-bus-carrier/pinout" target="_blank" rel="noreferrer">Matches ARK PAB Carrier Power Pinout</a></li></ul></li><li>4 Pin Molex CLIK-Mate 12V Output</li></ul></li><li><p><strong>Other</strong></p><ul><li>USA Built</li><li>Includes 6 Pin Molex CLIK-Mate Cable</li></ul></li><li><p><strong>Additional Information</strong></p><ul><li>Weight: 20.5 g</li><li>Dimensions: 3.7 cm x 3.5 cm x 1.3 cm</li></ul></li></ul><h2 id="px4-setup" tabindex="-1">PX4 Setup <a class="header-anchor" href="#px4-setup" aria-label="Permalink to &quot;PX4 Setup&quot;">​</a></h2><ul><li>Disable the <code>SENS_EN_INA226</code> parameter if it is enabled.</li><li>Enable the <code>SENS_EN_INA238</code> parameter.</li><li>Reboot the flight controller.</li><li>Set the <code>INA238_SHUNT</code> parameter to 0.0001.</li><li>Reboot the flight controller.</li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="https://docs.arkelectron.com/power/ark-12s-payload-power-module" target="_blank" rel="noreferrer">ARK 12S Payload Power Module Documentation</a> (ARK Docs)</li></ul>',13)])])}const P=a(i,[["render",n]]);export{m as __pageData,P as default};
